<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$pid=(int)($_GET['id']??$_POST['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['crear'])){$pdo->prepare('INSERT INTO plantillas(nombre,descripcion,activo) VALUES(?,?,1)')->execute([epost('nombre'),epost('descripcion')]);$pid=(int)$pdo->lastInsertId();ego('plantillas.php?id='.$pid);}
 if(isset($_POST['actualizar'])){$pdo->prepare('UPDATE plantillas SET nombre=?,descripcion=? WHERE id=?')->execute([epost('nombre'),epost('descripcion'),$pid]);ego('plantillas.php?id='.$pid);}
 if(isset($_POST['add_item'])){$cid=(int)$_POST['catalogo_id'];$s=$pdo->prepare('SELECT * FROM catalogo_servicios WHERE id=?');$s->execute([$cid]);if($r=$s->fetch())$pdo->prepare('INSERT INTO plantilla_items(plantilla_id,catalogo_id,concepto,cantidad,precio,costo_interno,responsable_sergio,responsable_ricardo,responsable_tomas,garantia_meses,tipo_entrega,dias_entrega_estimada,dias_trabajo_min,dias_trabajo_max) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0,0)')->execute([$pid,$cid,$r['nombre'].($r['descripcion']?' — '.$r['descripcion']:''),max(.01,(float)($_POST['cantidad']??1)),$r['precio_base'],$r['costo_base'],$r['responsable_sergio'],$r['responsable_ricardo'],$r['responsable_tomas'],$r['garantia_meses'],$r['tipo_entrega'],$r['dias_entrega_estimada']]);ego('plantillas.php?id='.$pid);}
 if(isset($_POST['del_item'])){$pdo->prepare('DELETE FROM plantilla_items WHERE id=? AND plantilla_id=?')->execute([(int)$_POST['row_id'],$pid]);ego('plantillas.php?id='.$pid);}
 if(isset($_POST['toggle'])){$pdo->prepare('UPDATE plantillas SET activo=IF(activo=1,0,1) WHERE id=?')->execute([$pid]);ego('plantillas.php');}
}
$templates=$pdo->query('SELECT p.*,(SELECT COUNT(*) FROM plantilla_items pi WHERE pi.plantilla_id=p.id) items FROM plantillas p ORDER BY activo DESC,nombre')->fetchAll();$p=null;$items=[];if($pid){$s=$pdo->prepare('SELECT * FROM plantillas WHERE id=?');$s->execute([$pid]);$p=$s->fetch()?:null;if($p){$s=$pdo->prepare('SELECT * FROM plantilla_items WHERE plantilla_id=? ORDER BY id');$s->execute([$pid]);$items=$s->fetchAll();}}$cat=$pdo->query('SELECT * FROM catalogo_servicios WHERE activo=1 ORDER BY nombre')->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Plantillas · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('catalogo');?><main class="w"><div class="srnu-page-heading"><div><h1>Plantillas de servicios</h1><p>Paquetes completos reutilizables para crear cotizaciones más rápido.</p></div><a class="btn light" href="catalogo.php">← Catálogo</a></div><div class="grid-2"><section class="panel" style="padding:18px"><h3>Nueva plantilla</h3><form method="post" class="erp-form"><input name="nombre" required placeholder="Ej. Detailing completo"><input name="descripcion" placeholder="Descripción interna"><button class="btn blue" name="crear" value="1">Crear plantilla</button></form><hr style="margin:18px 0;border:0;border-top:1px solid #ddd"><h3>Plantillas</h3><?php foreach($templates as $t):?><div class="card" style="margin-bottom:10px"><b><?=eh($t['nombre'])?></b><div class="muted"><?=$t['items']?> concepto(s) · <?=$t['activo']?'Activa':'Inactiva'?></div><div class="toolbar" style="margin-top:8px"><a class="btn light" href="?id=<?=$t['id']?>">Editar</a><a class="btn blue" href="cotizador.php?plantilla=<?=$t['id']?>">Usar en cotización</a><form method="post"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="btn <?=$t['activo']?'danger':'green'?>" name="toggle" value="1"><?=$t['activo']?'Desactivar':'Activar'?></button></form></div></div><?php endforeach;?></section><section class="panel" style="padding:18px"><?php if($p):?><h3>Editar <?=eh($p['nombre'])?></h3><form method="post" class="erp-form"><input type="hidden" name="id" value="<?=$pid?>"><input name="nombre" value="<?=eh($p['nombre'])?>"><input name="descripcion" value="<?=eh($p['descripcion'])?>"><button class="btn" name="actualizar" value="1">Guardar nombre</button></form><h3 style="margin-top:20px">Agregar concepto</h3><form method="post" class="toolbar"><input type="hidden" name="id" value="<?=$pid?>"><select name="catalogo_id" required><option value="">Servicio del catálogo</option><?php foreach($cat as $c):?><option value="<?=$c['id']?>"><?=eh($c['nombre'])?> · <?=srnu_tipo_entrega_label($c['tipo_entrega'])?></option><?php endforeach;?></select><input style="width:100px" type="number" step="0.01" min=".01" name="cantidad" value="1"><button class="btn blue" name="add_item" value="1">Agregar</button></form><table style="margin-top:14px"><tr><th>Concepto</th><th>Cant.</th><th>Precio</th><th>Tipo</th><th></th></tr><?php foreach($items as $it):?><tr><td><?=eh($it['concepto'])?></td><td><?=eh($it['cantidad'])?></td><td><?=emoney($it['precio'])?></td><td><?=srnu_tipo_entrega_label($it['tipo_entrega'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$pid?>"><input type="hidden" name="row_id" value="<?=$it['id']?>"><button class="btn danger" name="del_item" value="1">Quitar</button></form></td></tr><?php endforeach;?></table><p><a class="btn blue" href="cotizador.php?plantilla=<?=$pid?>">Crear cotización con esta plantilla</a></p><?php else:?><p class="muted">Selecciona una plantilla para editar sus conceptos.</p><?php endif;?></section></div></main></body></html>
